INSERT INTO people (id, canonical_name, first_name, last_name, country, occupation, industry, description, is_billionaire, giving_pledge) VALUES
('b0000000-0000-0000-0000-000000000001', 'Warren Buffett', 'Warren', 'Buffett', '🇺🇸 United States', 'Chairman & CEO, Berkshire Hathaway', 'Finance & Investing', 'Has pledged to give away more than 99% of his fortune, primarily via annual Berkshire Hathaway Class B share transfers to the Gates Foundation and his family foundations.', true, true),
('b0000000-0000-0000-0000-000000000002', 'Bill Gates', 'William', 'Gates', '🇺🇸 United States', 'Co-Chair, Bill & Melinda Gates Foundation', 'Technology & Philanthropy', 'Co-founder of Microsoft and Co-Chair of the Gates Foundation. Converted substantial personal Microsoft equity to establish one of the world''s largest private endowments.', true, true),
('b0000000-0000-0000-0000-000000000003', 'MacKenzie Scott', 'MacKenzie', 'Scott', '🇺🇸 United States', 'Philanthropist & Author', 'Philanthropy & Literature', 'Pioneered rapid, unrestricted direct grants to hundreds of community-focused non-profits globally, publishing complete verified grant registries on Yield Giving.', true, true),
('b0000000-0000-0000-0000-000000000004', 'Elon Musk', 'Elon', 'Musk', '🇺🇸 United States', 'CEO, Tesla & SpaceX', 'Technology & Automotive', 'CEO of Tesla and SpaceX. Philanthropic capital transfers primarily executed via Tesla stock transfers to donor-advised funds (DAFs) and the Musk Foundation.', true, true),
('b0000000-0000-0000-0000-000000000005', 'Azim Premji', 'Azim', 'Premji', '🇮🇳 India', 'Founder & Chairman, Wipro / Azim Premji Foundation', 'Information Technology', 'First Indian signatory of the Giving Pledge. Irrevocably transferred over $21 Billion (74% of economic ownership in Wipro) into a perpetual charitable trust for rural education.', true, true),
('b0000000-0000-0000-0000-000000000006', 'Andrew Carnegie (Historic)', 'Andrew', 'Carnegie', '🏴󠁧󠁢󠁳󠁣󠁴󠁿 Scotland / 🇺🇸 US', 'Industrialist & Philanthropist', 'Steel & Heavy Industry', 'Author of ''The Gospel of Wealth'' (1889). Gave away over 90% of his fortune (~$350 million in 1900, roughly $350 billion in modern relative economic share), building 2,509 public libraries.', true, true),
('b0000000-0000-0000-0000-000000000007', 'John D. Rockefeller (Historic)', 'John', 'Rockefeller', '🇺🇸 United States', 'Industrialist & Philanthropist', 'Petroleum & Energy', 'America''s first billionaire. Given over $540 million in personal fortune, establishing modern biomedical research institutes, the University of Chicago, and the Rockefeller Foundation.', true, true),
('b0000000-0000-0000-0000-000000000008', 'Mukesh Ambani', 'Mukesh', 'Ambani', '🇮🇳 India', 'Chairman & Managing Director, Reliance Industries', 'Energy, Telecom & Retail', 'Chairman of Reliance Industries. Philanthropy is conducted primarily through the Reliance Foundation funded by Reliance Industries statutory CSR disbursements.', true, false),
('b0000000-0000-0000-0000-000000000009', 'Gautam Adani', 'Gautam', 'Adani', '🇮🇳 India', 'Founder & Chairman, Adani Group', 'Infrastructure & Energy', 'Chairman of the Adani Group. Announced a non-binding ₹60,000 Crore pledge on his 60th birthday; ongoing philanthropy managed via the Adani Foundation corporate CSR.', true, false),
('b0000000-0000-0000-0000-000000000010', 'Carlos Slim', 'Carlos', 'Slim', '🇲🇽 Mexico', 'Honorary Chairman, América Móvil / Grupo Carso', 'Telecommunications & Industry', 'Telecom magnate. Operates the Carlos Slim Foundation focusing on health, digital classrooms, and Latin American genomic research.', true, false),
('b0000000-0000-0000-0000-000000000011', 'Jack Ma', 'Jack', 'Ma', '🇨🇳 China', 'Co-Founder, Alibaba Group / Founder, Jack Ma Foundation', 'E-Commerce & Tech', 'Co-founder of Alibaba. Transferred 35 million share options at Alibaba''s IPO to establish the Jack Ma Foundation supporting rural teachers and global disaster relief.', true, false),
('b0000000-0000-0000-0000-000000000012', 'Michael Bloomberg', 'Michael', 'Bloomberg', '🇺🇸 United States', 'Founder, Bloomberg LP & Bloomberg Philanthropies', 'Media & Finance', 'Founder of Bloomberg LP. Committed nearly his entire fortune to Bloomberg Philanthropies, alongside landmark direct personal gifts to Johns Hopkins University.', true, true),
('b0000000-0000-0000-0000-000000000013', 'Mark Zuckerberg & Priscilla Chan', 'Mark', 'Zuckerberg', '🇺🇸 United States', 'Founder & CEO, Meta / Co-Founders, Chan Zuckerberg Initiative', 'Technology', 'Chan Zuckerberg Initiative (CZI) combines 501(c)(3) foundation grantmaking and LLC investments to cure, prevent, or manage all diseases by the end of the century.', true, true),
('b0000000-0000-0000-0000-000000000014', 'Jeff Bezos', 'Jeff', 'Bezos', '🇺🇸 United States', 'Executive Chair, Amazon / Founder, Bezos Earth Fund', 'Tech & Commerce', 'Founder of Amazon. Philanthropic giving concentrated in the Bezos Earth Fund and Bezos Day One Fund, alongside direct civic donations.', true, false),
('b0000000-0000-0000-0000-000000000015', 'Larry Ellison', 'Larry', 'Ellison', '🇺🇸 United States', 'Chief Technology Officer & Executive Chair, Oracle', 'Enterprise Software', 'Co-founder of Oracle. Giving Pledge signatory (2010); major gifts support oncology research institutes and conservation on the island of Lanai.', true, true),
('b0000000-0000-0000-0000-000000000016', 'Bernard Arnault & Family', 'Bernard', 'Arnault', '🇫🇷 France', 'Chairman & CEO, LVMH', 'Luxury Goods', 'Chairman and CEO of LVMH. Philanthropy executed primarily through LVMH corporate treasury and family holding contributions toward French cultural heritage.', true, false),
('b0000000-0000-0000-0000-000000000017', 'Steve & Connie Ballmer', 'Steve', 'Ballmer', '🇺🇸 United States', 'Co-Founders, Ballmer Group / Former CEO, Microsoft', 'Tech & Sports', 'Champions data-driven philanthropic giving focusing on economic mobility for impoverished youth and racial equity through the Ballmer Group.', true, true),
('b0000000-0000-0000-0000-000000000018', 'Chuck Feeney (Historic)', 'Charles', 'Feeney', '🇺🇸 United States / 🇮🇪 Ireland', 'Co-Founder, Duty Free Shoppers (DFS) / Philanthropist', 'Retail & Duty Free', 'The global pioneer of ''Giving While Living''. Secretly transferred his entire 38.75% stake in Duty Free Shoppers into Atlantic Philanthropies in 1984, successfully giving away all $8 Billion and dying with $2M in personal savings.', true, true),
('b0000000-0000-0000-0000-000000000019', 'George Soros', 'George', 'Soros', '🇺🇸 United States / 🇭🇺 Hungary', 'Founder, Soros Fund Management / Open Society Foundations', 'Hedge Funds & Investing', 'Renowned macro investor. Transferred $18 Billion from his personal hedge fund in 2017 to the Open Society Foundations to champion human rights, public health, and democratic institutions.', true, true),
('b0000000-0000-0000-0000-000000000020', 'Gordon Moore (Historic)', 'Gordon', 'Moore', '🇺🇸 United States', 'Co-Founder, Intel Corporation / Philanthropist', 'Semiconductors & Technology', 'Co-founder of Intel and formulator of Moore''s Law. With his wife Betty, donated 175 million Intel shares ($5 Billion) in 2000 to endow the Gordon and Betty Moore Foundation.', true, true),
('b0000000-0000-0000-0000-000000000021', 'Pierre Omidyar & Pam Omidyar', 'Pierre', 'Omidyar', '🇺🇸 United States / 🇫🇷 France', 'Founder, eBay / Co-Founder, Omidyar Network', 'E-Commerce & Tech', 'Founder of eBay. Giving Pledge signatory (2010); operates the Omidyar Network and Democracy Fund, pioneering philanthropic impact investing.', true, true),
('b0000000-0000-0000-0000-000000000022', 'Shiv Nadar', 'Shiv', 'Nadar', '🇮🇳 India', 'Founder, HCL Group & Shiv Nadar Foundation', 'Information Technology', 'Founder of HCL. Repeatedly ranked #1 in the EdelGive Hurun India Philanthropy List. Has personal contributions exceeding ₹2,000 Crore annually dedicated to transformative education.', true, false),
('b0000000-0000-0000-0000-000000000023', 'Michael Dell & Susan Dell', 'Michael', 'Dell', '🇺🇸 United States', 'Chairman & CEO, Dell Technologies / Philanthropists', 'Computer Hardware & Cloud', 'Chairman and CEO of Dell Technologies. Donated $1 Billion to the Michael & Susan Dell Foundation in 2006 to advance child health, urban education, and family economic stability.', true, true),
('b0000000-0000-0000-0000-000000000024', 'Sergey Brin', 'Sergey', 'Brin', '🇺🇸 United States', 'Co-Founder, Google / Board Member, Alphabet', 'Internet & Technology', 'Co-founder of Google. Has directed over $1.1 Billion in personal gifts and foundation grants to accelerate research into Parkinson''s disease treatments.', true, false),
('b0000000-0000-0000-0000-000000000025', 'Larry Page', 'Larry', 'Page', '🇺🇸 United States', 'Co-Founder, Google / Board Member, Alphabet', 'Internet & Technology', 'Co-founder of Google. Primary philanthropic contributions executed through substantial annual transfers of Alphabet equity to the Carl Victor Page Memorial Foundation.', true, false)
