-- ==============================================================================
-- NoCharity Supabase Migration: 20261022000008_phase13_high_quality_seed.sql
-- Phase 13: High-Quality Initial Dataset (25 Rigorously Audited Billionaires)
-- ==============================================================================

-- 1. UPSERT 25 CANONICAL PEOPLE
ON CONFLICT (id) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    first_name = EXCLUDED.first_name,
    last_name = EXCLUDED.last_name,
    country = EXCLUDED.country,
    occupation = EXCLUDED.occupation,
    industry = EXCLUDED.industry,
    description = EXCLUDED.description,
    is_billionaire = EXCLUDED.is_billionaire,
    giving_pledge = EXCLUDED.giving_pledge,
    updated_at = NOW();

-- 2. UPSERT ORGANIZATIONS
ON CONFLICT (id) DO UPDATE SET
    legal_name = EXCLUDED.legal_name,
    display_name = EXCLUDED.display_name,
    organization_type = EXCLUDED.organization_type,
    ein = COALESCE(EXCLUDED.ein, organizations.ein),
    cik = COALESCE(EXCLUDED.cik, organizations.cik),
    website = COALESCE(EXCLUDED.website, organizations.website),
    updated_at = NOW();

-- 3. LINK PERSON_ORGANIZATIONS
ON CONFLICT (person_id, organization_id, relationship_type) DO NOTHING;

-- 4. UPSERT VERIFIABLE SOURCES
ON CONFLICT (id) DO UPDATE SET
    url = EXCLUDED.url,
    publisher = EXCLUDED.publisher,
    title = EXCLUDED.title,
    source_type = EXCLUDED.source_type,
    updated_at = NOW();

-- 5. UPSERT HISTORICAL WEALTH SNAPSHOTS
ON CONFLICT (person_id, snapshot_date) DO UPDATE SET
    net_worth = EXCLUDED.net_worth,
    currency = EXCLUDED.currency,
    source_name = EXCLUDED.source_name,
    source_id = COALESCE(EXCLUDED.source_id, wealth_snapshots.source_id),
    confidence = EXCLUDED.confidence;

-- 6. UPSERT DOCUMENTED DONATIONS (PERSONAL, FOUNDATION & CORPORATE)
ON CONFLICT (id) DO UPDATE SET
    donor_person_id = EXCLUDED.donor_person_id,
    donor_organization_id = EXCLUDED.donor_organization_id,
    amount = EXCLUDED.amount,
    currency = EXCLUDED.currency,
    donation_date = EXCLUDED.donation_date,
    donation_type = EXCLUDED.donation_type,
    funding_source_type = EXCLUDED.funding_source_type,
    status = EXCLUDED.status,
    description = EXCLUDED.description,
    cause_category = EXCLUDED.cause_category,
    source_id = EXCLUDED.source_id,
    updated_at = NOW();

-- 7. LINK DONATION_SOURCES
ON CONFLICT (donation_id, source_id) DO NOTHING;

-- 8. EXPLICITLY MARKED TEST FIXTURE (FOR PARITY/REGRESSION EDGE-CASE TESTING)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title;

ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description, status = EXCLUDED.status;

ON CONFLICT (donation_id, source_id) DO NOTHING;
